// disk_free_bytes is null when the host could not read the volume; a full disk is 0.
type RuntimeStatus={inference:boolean;whisper:boolean;llama:boolean;disk_free_bytes:number|null};
const freeDiskText=(runtime:RuntimeStatus|null)=>runtime&&runtime.disk_free_bytes!==null?`${(runtime.disk_free_bytes/1e9).toFixed(1)} GB`:'';
