// The worker already keeps notes to what was said and drops timestamps (engine.py::note_style), so these need not ask.
const promptExamples=[
  {name:'Case note',text:'This is a one-to-one counselling session. Write a short case note with these headings: Presenting concerns, What the client shared, Support offered, Agreed next steps. Use short bullet points and keep it under 200 words. Leave out small talk.'},
  {name:'Team meeting',text:'This is a team meeting. Use these headings: Updates, Issues raised, Decisions, Actions. For each action, say who will do it and by when, if that was said. Keep each point to one line.'},
  {name:'Training session',text:'This is a training session. Use these headings: Topics covered, Key points, Questions asked, To follow up. Write in plain English with short bullet points.'},
];
// Setup installs only the chosen transcription model; either one transcribes (Service::transcription_model).
const canTranscribe=(list:Model[])=>list.some(m=>(m.id==='whisper'||m.id==='parakeet')&&m.present);
const notesHeadings:Record<string,[string,string]>={counselling:['Session notes.','Themes, concerns and agreed next steps from your transcript. Review before sharing.'],service:['Conversation notes.','Reason for contact, support discussed and follow-up from your transcript. Review before sharing.'],meeting:['Meeting notes.','Topics, decisions and next steps from your transcript. Review before sharing.'],custom:['Notes.','Written to your instructions from the transcript. Review before sharing.']};
const styleHelp:Record<string,string>={counselling:'Main concerns, feelings and experiences, strengths and supports, and agreed next steps. No diagnosis, labels or advice that was not said.',service:'Reason for contact, information shared, support or options discussed, and agreed follow-up.',meeting:'Discussion points, decisions, action items and next steps.',custom:'Describe what the notes should contain and how to organise them.'};
const size=(bytes:number)=>bytes>=1e9?`${(bytes/1e9).toFixed(2)} GB`:`${Math.round(bytes/1e6)} MB`;

// Windows asks nothing of a desktop app; it blocks the microphone while one
// Settings switch is off. The backend's message names that switch.
const blocksMicrophone=(message:string)=>message.includes('Let desktop apps access your microphone');
function MicrophoneSettings({onError}:{onError:(message:string)=>void}){return <button className="secondary" onClick={()=>void api('open_microphone_settings').catch(e=>onError(String(e)))}>Open microphone settings</button>;}

